  { module: '审批', user: '查看 + 决定（自己的会话内）', admin: '查看 + 决定（自己的会话内）' },
  { module: '审计', user: '查看（仅自己的）', admin: '查看（全局，可按操作者/资源筛选）' },
  { module: '平台密钥', user: '—（无权限）', admin: '查看 + 管理（CRUD/轮换/启停）' },
  { module: '管理台', user: '—（无权限）', admin: '查看 + 管理（/admin/* 全部页面）' },
]

